// Package perm would be generated by gen:authz from package model. Each
// permission is bound to its object type at compile time.
package perm

import (
	"github.com/speakeasy-api/gram/spikes/clean-slate-authz/authz"
	"github.com/speakeasy-api/gram/spikes/clean-slate-authz/objects"
)

var (
	OrganizationCreateAgent  = authz.Permission[objects.Organization]{Type: "organization", Name: "create_agent"}
	OrganizationManageAccess = authz.Permission[objects.Organization]{Type: "organization", Name: "manage_access"}
	ProjectRead              = authz.Permission[objects.Project]{Type: "project", Name: "read"}
	ProjectWrite             = authz.Permission[objects.Project]{Type: "project", Name: "write"}
	MCPServerRead            = authz.Permission[objects.MCPServer]{Type: "mcp_server", Name: "read"}
	MCPServerEdit            = authz.Permission[objects.MCPServer]{Type: "mcp_server", Name: "edit"}
	MCPServerConnect         = authz.Permission[objects.MCPServer]{Type: "mcp_server", Name: "connect"}
	AgentManage              = authz.Permission[objects.Agent]{Type: "agent", Name: "manage"}
	AgentRead                = authz.Permission[objects.Agent]{Type: "agent", Name: "read"}
	UserReviewActivity       = authz.Permission[objects.User]{Type: "user", Name: "review_activity"}
	ChatRead                 = authz.Permission[objects.Chat]{Type: "chat", Name: "read"}
)
